  if(name.includes('Pad')) return {...base,cut:1600,res:1,a:.7,d:1,s:.85,r:1.4,det:16,det2:10};
  if(name.includes('Pluck')||name.includes('Stab')) return {...base,wave:'triangle',wave2:'sine',cut:2600,env:.8,a:.002,d:.22,s:0,r:.15};
  if(name.includes('Acid')) return {...base,cut:900,res:13,env:.9,a:.003,d:.16,s:.2,lfoD:.25};
  if(name.includes('Lead')) return {...base,cut:3400,det:12,unison:3};
